import {
  BooleanInput,
  NumberInput,
  coerceBooleanProperty,
  coerceNumberProperty,
} from '@angular/cdk/coercion';
import { hasModifierKey } from '@angular/cdk/keycodes';
import { NgClass } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { accordionAnimations } from '@questrade/allspark-angular-components/core/animations';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { chevronDown } from '@questrade/allspark-icons/icons';

@Component({
  imports: [NgClass, QIconComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  animations: [accordionAnimations.triggerRotate],
  selector: 'q-expansion-trigger',
  template: `
    <q-icon
      [name]="'chevronDown'"
      class="q-expansion-trigger-icon"
      [ngClass]="{ 'q-expansion-trigger-disabled': disabled }"
      [size]="'24'"
      [dataQt]="'q-expansion-trigger-chevron'"
      [@triggerRotate]="active ? 'expanded' : 'collapsed'" />
  `,
  styleUrl: './expansion-trigger.component.scss',
})
export class QExpansionTriggerComponent {
  @Output() readonly activeChange = new EventEmitter<boolean>();

  @Input({ transform: booleanAttribute }) @HostBinding('attr.aria-expanded') active = false;

  @Input() @HostBinding('attr.tabIndex') get tabIndex(): number {
    return this.disabled ? -1 : this._tabIndex;
  }
  set tabIndex(value: NumberInput) {
    this._tabIndex = coerceNumberProperty(value, 0);
  }

  @Input() get disabled(): boolean {
    return this._disabled;
  }
  set disabled(value: BooleanInput) {
    this._disabled = coerceBooleanProperty(value);

    if (this.disabled) {
      this.active = false;
    }
  }

  @HostBinding('attr.role') _role = 'button';

  @HostBinding('attr.class') get _hostClasses(): string {
    return ['q-expansion-trigger', this._tabIndex > -1 && !this.disabled && 'q-focus-indicator']
      .filter(Boolean)
      .join(' ');
  }

  @HostListener('click', ['$event']) _onClick = (): void => this.onTriggerInteraction();
  @HostListener('keydown', ['$event']) _onKeydown = (event: KeyboardEvent): void =>
    this.onKeydown(event);

  private _disabled = false;
  private _tabIndex = 0;
  private _iconRegistry = inject(QIconRegistryService);

  constructor() {
    this._iconRegistry.registerIcon(chevronDown);
  }

  onTriggerInteraction(): void {
    if (!this.disabled) {
      this.toggle();
      this.activeChange.emit(this.active);
    }
  }

  toggle(): void {
    this.active = !this.active;
  }

  onKeydown(event: KeyboardEvent): void {
    switch (event.code) {
      case SPACE:
      case ENTER:
        if (!hasModifierKey(event)) {
          event.preventDefault();
          this.onTriggerInteraction();
        }

        break;
      default:
        return;
    }
  }
}
